<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $chalanNos = ["59", "61", "62"]; $billItems = \App\Models\GenerateBillItem::whereIn("sr_no", $chalanNos)->whereHas("generateBill", function($q) { $q->where("is_draft", false); })->with(["generateBill" => function($q) { $q->where("is_draft", false); }])->get(); echo "Found " . $billItems->count() . " items.\n"; foreach($chalanNos as $cNo) { $item = $billItems->firstWhere("sr_no", $cNo); echo "Chalan: " . $cNo . " => " . ($item ? "Matched, bill_no=" . ($item->generateBill ? $item->generateBill->bill_no : "null bill") : "Not matched") . "\n"; }
